	if err != nil {
		return err
	}
	input, err := buildTrailReviewCommentInput(opts)
	if err != nil {
		return err
	}
	created, err := createTrailReviewFinding(cmd.Context(), client, target.Trail.ID, input)
	if err != nil {
		return err
	}
	if opts.JSON {
